extern "C" void NCollection_Sequence_gp_XYZ_clear(NCollection_Sequence_gp_XYZ* coll) {
    coll->Clear();
}

extern "C" void NCollection_Sequence_gp_XYZ_append(NCollection_Sequence_gp_XYZ* coll, const gp_XYZ* item) {
    coll->Append(*item);
}

extern "C" const gp_XYZ* NCollection_Sequence_gp_XYZ_value(const NCollection_Sequence_gp_XYZ* coll, int index) {
    return &coll->Value(index);
}

// ========================
// NCollection_Sequence_int - Dynamic array (1-indexed)
// ========================

typedef NCollection_Sequence<int> NCollection_Sequence_int;

extern "C" NCollection_Sequence_int* NCollection_Sequence_int_new() {
    return new NCollection_Sequence_int();
}

extern "C" void NCollection_Sequence_int_destructor(NCollection_Sequence_int* self_) {
    delete self_;
}

struct Sequence_intIterator {
    const NCollection_Sequence_int* coll;
    int index;  // 1-indexed (OCCT convention)
    int extent;
};

extern "C" void Sequence_intIterator_destructor(Sequence_intIterator* self_) {
    delete self_;
}

extern "C" Sequence_intIterator* NCollection_Sequence_int_iter(const NCollection_Sequence_int* coll) {
    auto iter = new Sequence_intIterator();
    iter->coll = coll;
    iter->index = 1;
    iter->extent = coll->Length();
    return iter;
}

extern "C" int* Sequence_intIterator_next(Sequence_intIterator* iter) {
    if (iter->index > iter->extent) {
        return nullptr;
    }
    auto* result = const_cast<int*>(&iter->coll->Value(iter->index));
    ++iter->index;
    return result;
}

extern "C" int NCollection_Sequence_int_size(const NCollection_Sequence_int* coll) {
    return coll->Length();
}

extern "C" void NCollection_Sequence_int_clear(NCollection_Sequence_int* coll) {
    coll->Clear();
}

extern "C" void NCollection_Sequence_int_append(NCollection_Sequence_int* coll, const int* item) {
    coll->Append(*item);
}

extern "C" const int* NCollection_Sequence_int_value(const NCollection_Sequence_int* coll, int index) {
    return &coll->Value(index);
}

